)
"'$pats = @(
  '"'settings put','settings delete','pm enable','pm disable','appops set','cmd appops','rollback','kill-server','adb shell settings','pm hide','pm unhide','cmd overlay enable','cmd overlay disable','svc power','am force-stop','input swipe','input tap'
)
foreach ("'$root in $roots) {
  Write-Output "===== ROOT $root ====="
  $files = Get-ChildItem -Path $root -Recurse -Force -Filter *.py -ErrorAction SilentlyContinue
